// The existing OCR/matcher and v1 storage remain the source of truth.
const F={translations:new Map(),photos:[],sourceObserver:null,refObserver:null,activeObserver:null,selection:null,mobilePane:'source',lookup:null,chatKey:null,controller:null,config:null,hydrating:false};
const baseOpenPage=openPage,baseQuestions=renderQuestions,baseSetAnswer=setAnswer,baseStorePhoto=storePhoto;
const FLOW_KEY='english-flow.v1';let flowCorrupt=false;let flowData={schemaVersion:1,chats:{},vocabulary:{},confirmed:{},mastered:{},analysisCache:{}};
try{const raw=localStorage.getItem(FLOW_KEY);if(raw){const v=JSON.parse(raw);if(v.schemaVersion!==1)throw Error();for(const k of Object.keys(flowData))if(k!=='schemaVersion'&&v[k]&&typeof v[k]==='object'&&!Array.isArray(v[k]))flowData[k]=v[k]}}catch{flowCorrupt=true;toast('新版记录读取失败，原数据保留，请导出备份。')}
function saveFlow(){try{if(flowCorrupt){const raw=localStorage.getItem(FLOW_KEY);if(raw)localStorage.setItem(FLOW_KEY+'.recovery',raw);flowCorrupt=false}localStorage.setItem(FLOW_KEY,JSON.stringify(flowData))}catch{toast('存储空间不足，请导出备份；本次记录仍在页面内。')}}
function pageById(id){return U.pages.find(p=>p.id===id)}
function make(tag,cls,text){const el=document.createElement(tag);if(cls)el.className=cls;if(text!==undefined)el.textContent=text;return el}
function mobilePane(p){F.mobilePane=p;$('.work-columns').dataset.mobilePane=p;document.querySelectorAll('[data-mobile]').forEach(b=>b.classList.toggle('active',b.dataset.mobile===p))}
async function translations(year){if(!F.translations.has(year)){try{F.translations.set(year,await json('library/translations/'+year+'.json'))}catch{return {sentences:[]}}}return F.translations.get(year)}
function sentenceFor(page,index){return (F.translations.get(page.year)?.sentences||[]).find(s=>s.page===page.page&&index>=s.startWord&&index<=s.endWord)}
function currentSource(){return F.selection?.page||U.page}
function updateLocation(page,changeQuestion=false){if(!page)return;U.page=page;$('#pageSelect').value=page.id;$('#workTitle').textContent=page.year+' 英语二 · '+page.section;$('#flowLocation').textContent='第 '+page.page+' 页 · '+page.section;if(changeQuestion){if(F.selection?.page.id!==page.id){F.selection=null;F.lookup=null}U.question=activeQuestions().some(q=>q.number===U.question)?U.question:activeQuestions()[0]?.number||null;renderQuestions()}}
function streamObserve(container,pages,render,kind){const root=matchMedia('(min-width:1051px)').matches?container:null;const io=new IntersectionObserver(entries=>{for(const entry of entries){const el=entry.target;const p=pages.find(p=>String(p.page)===el.dataset.streamPage);if(entry.isIntersecting){if(!el.dataset.loaded){render(el,p);el.dataset.loaded='1'}}else if(el.dataset.loaded){const body=el.querySelector('.flow-body');const height=body.getBoundingClientRect().height;if(height>0){body.style.minHeight=height+'px';body.replaceChildren();delete el.dataset.loaded}}}},{root,rootMargin:'900px 0px'});for(const el of container.querySelectorAll('.flow-page'))io.observe(el);return io}
function sourceMarkup(el,page){const body=el.querySelector('.flow-body');body.replaceChildren();body.style.minHeight='';const photo=F.photos.find(p=>p.pageId===page.id);if(U.view==='text'){const sheet=make('div','text-sheet');sheet.style.fontSize=(19*U.zoom)+'px';page.words.forEach((w,i)=>{const b=make('button','word-token',w.text);b.dataset.flowWord=i;b.dataset.pageId=page.id;b.setAttribute('aria-label','点读 '+w.text);sheet.append(b,document.createTextNode(' '));if(page.words[i+1]?.y-w.y>3.5)sheet.append(make('br'))});body.append(sheet);return}if(U.view==='photo'&&!photo){body.append(make('div','flow-placeholder','本页尚未上传作答照片 · 可切换清晰原题'));return}const wrap=make('div','source-image'),img=make('img');img.src=U.view==='photo'?photo.url:page.image;img.alt=page.year+' 年第 '+page.page+' 页';img.decoding='async';img.loading='lazy';wrap.append(img);const words=U.view==='photo'?photo.words:page.words,svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 100 100');svg.setAttribute('preserveAspectRatio','none');for(let i=0;i<words.length;i++){const w=words[i],r=document.createElementNS(svg.namespaceURI,'rect');for(const [k,v]of Object.entries({x:w.x,y:w.y,width:w.w,height:w.h,fill:'transparent',stroke:'transparent',tabindex:0,role:'button','aria-label':'点读 '+w.text}))r.setAttribute(k,v);r.classList.add('hit');r.dataset.flowHit=i;r.dataset.pageId=page.id;svg.append(r)}wrap.append(svg);wrap.style.width=U.zoom*100+'%';body.append(wrap)}
renderSource=function(){F.sourceObserver?.disconnect();F.activeObserver?.disconnect();document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===U.view);b.disabled=false});syncMode();const c=$('#sourceContent'),pages=U.pages.filter(p=>p.year===U.page.year);c.replaceChildren();for(const page of pages){const el=make('article','flow-page');el.id='source-'+page.id;el.dataset.streamPage=page.page;el.append(make('h3','',page.year+' 英语二 · 第 '+page.page+' 页 · '+page.section),make('div','flow-body'));el.lastChild.style.minHeight=Math.max(1,(c.clientWidth-24)*(page.imageHeight/page.imageWidth||1.414))+'px';c.append(el);if(U.view==='text'){sourceMarkup(el,page);el.dataset.loaded='1'}}if(U.view!=='text')F.sourceObserver=streamObserve(c,pages,sourceMarkup,'source');F.activeObserver=new IntersectionObserver(entries=>{const visible=entries.filter(e=>e.isIntersecting).sort((a,b)=>Math.abs(a.boundingClientRect.top)-Math.abs(b.boundingClientRect.top));if(visible.length&&!F.hydrating&&!F.opening){const p=pages.find(p=>p.page===Number(visible[0].target.dataset.streamPage));if(p&&p.id!==U.page.id)updateLocation(p,true)}},{root:matchMedia('(min-width:1051px)').matches?c:null,rootMargin:'-10% 0px -65% 0px'});c.querySelectorAll('.flow-page').forEach(el=>F.activeObserver.observe(el));jumpSource(U.page.id)};
function jumpSource(id,index=null){const el=document.getElementById('source-'+id),p=pageById(id);if(!el||!p)return;F.hydrating=true;if(!el.dataset.loaded){sourceMarkup(el,p);el.dataset.loaded='1'}el.scrollIntoView({block:'start',behavior:'instant'});if(index!==null){const target=el.querySelector('[data-flow-word="'+index+'"]')||el.querySelector('[data-flow-hit="'+index+'"]');target?.classList.add('selected');target?.scrollIntoView({block:'center',behavior:'smooth'})}setTimeout(()=>F.hydrating=false,250)}
openPage=async function(page,photo=null,message){if(!page)return;F.opening=true;F.selection=null;F.lookup=null;mobilePane('source');for(const old of F.photos){if(old.url){URL.revokeObjectURL(old.url);U.urls=U.urls.filter(u=>u!==old.url)}}F.photos=await dbAction('readonly',s=>s.getAll()).catch(()=>[]);for(const p of F.photos){p.url=URL.createObjectURL(p.blob);U.urls.push(p.url)}if(photo&&!F.photos.some(p=>p.id===photo.id))F.photos.push(photo);await translations(page.year);await baseOpenPage(page,photo,message);$('#quickbar').hidden=false;mobilePane('source');updateLocation(page,true);jumpSource(page.id);setTimeout(()=>F.opening=false,350)};
function syncMode(){document.querySelectorAll('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===U.mode);b.setAttribute('aria-pressed',String(b.dataset.mode===U.mode))})}
renderReference=function(sentence=null,matched=true){F.refObserver?.disconnect();const refs=U.refs.get(U.page.year)||[],c=$('#detailContent');c.replaceChildren();if(sentence)c.append(make('p','sentence-box',sentence));c.append(make('p','source-tag','原书解析 · '+(refs[0]?.source||meta(U.page.year).sourceReference||'用户导入解析')));const stream=make('div','reference-stream');for(const p of refs){const el=make('article','flow-page');el.id='reference-'+U.page.year+'-'+p.page;el.dataset.streamPage=p.page;el.append(make('h3','',U.page.year+' 年解析 · PDF 第 '+p.page+' 页'),make('div','flow-body'));el.lastChild.style.minHeight=Math.max(1,(c.clientWidth-36)*(p.imageHeight/p.imageWidth||1.414))+'px';stream.append(el)}c.append(stream);F.refObserver=streamObserve(c,refs,(el,p)=>{const body=el.querySelector('.flow-body');body.replaceChildren();body.style.minHeight='';const img=make('img','reference-image');img.src=p.image;img.alt='原书解析 PDF 第 '+p.page+' 页';img.loading='lazy';img.decoding='async';img.onclick=()=>dialog('原书解析 · PDF 第 '+p.page+' 页','<img class="full-ref" src="'+esc(p.image)+'" alt="原书解析">');body.append(img)},'reference');document.getElementById('reference-'+U.page.year+'-'+U.refPage)?.scrollIntoView({block:'start',behavior:'instant'})};
async function localLookup(page,index,text){F.selection={page,index,text};updateLocation(page);await translations(page.year);const s=sentenceFor(page,index),token=s?.tokens.find(t=>t.wordIndex===index),entry=dictionaryWord(text);F.lookup={page,index,text};U.lookup=null;setPanel('lookup');const c=$('#detailContent');c.replaceChildren();const panel=make('section','read-panel');panel.append(make('span','source-tag','本地点读 · 本次不调用 AI'),make('h2','lookup-word',U.mode==='sentence'?'句子精读':text));if(s?.translation){if(U.mode==='word'){panel.append(make('p','reading-zh',token?.contextMeaning||token?.kaoyanMeaning||'该词的语境义尚待生成'),make('p','muted',[token?.partOfSpeech,token?.lemma].filter(Boolean).join(' · ')));if(token?.collocations?.length)panel.append(make('p','', '搭配：'+token.collocations.join('；')));if(token?.familiarButRareMeaning)panel.append(make('p','', '熟词僻义：'+token.familiarButRareMeaning));if(token?.paraphrases?.length)panel.append(make('p','', '同义替换：'+token.paraphrases.join('；')))}panel.append(make('div','sentence-box',s.english),make('p','reading-zh',s.translation));if(s.grammar)panel.append(make('p','',s.grammar));panel.append(make('p','muted',s.generationModel==='legacy-import'?'译文来自保留的 2010 精读数据':'预生成译文 · '+s.generationModel))}else{panel.append(make('p','pending-tag','本句语境翻译待批量生成。当前保留原文与原书解析，未使用词典拼接译文。'),make('p','sentence-box',s?.english||sentenceAt(index)||text))}if(U.mode==='word'){const details=make('details');details.append(make('summary','','普通词典完整义项'),make('p','definition',entry.zh||'未收录'));panel.append(details);const states=make('div','vocab-state'),key=page.id+':'+index;for(const label of ['认识','模糊','不认识']){const b=make('button',flowData.vocabulary[key]?.state===label?'active':'',label);b.onclick=()=>{flowData.vocabulary[key]={state:label,word:text,sentence:s?.english||sentenceAt(index),translation:s?.translation||null,pageId:page.id,index};saveFlow();localLookup(page,index,text)};states.append(b)}panel.append(states)}const actions=make('div','flow-actions');for(const [label,fn]of [['定位原文',()=>{mobilePane('source');jumpSource(page.id,index)}],['查看原书解析',()=>{showExplanation(s?.english||page.text,true);mobilePane('review')}],['问 AI',()=>openChat()]]){const b=make('button','',label);b.onclick=fn;actions.append(b)}panel.append(actions);c.append(panel);mobilePane('review')}
document.addEventListener('click',e=>{const b=e.target.closest('[data-flow-word],[data-flow-hit],[data-mode],[data-question]');if(!b)return;e.stopImmediatePropagation();if(b.dataset.question){const q=Number(b.dataset.question),page=U.pages.find(p=>p.year===U.page.year&&p.questions.some(v=>v.number===q));if(page){updateLocation(page);U.question=q;renderQuestions();const index=page.words.findIndex(w=>w.text.replace(/[^0-9]/g,'')===String(q));jumpSource(page.id,index>=0?index:null);showExplanation();}return}if(b.dataset.mode){U.mode=b.dataset.mode;syncMode();if(F.lookup)localLookup(F.lookup.page,F.lookup.index,F.lookup.text);return}document.querySelectorAll('.selected,[aria-pressed=true].word-token').forEach(x=>{x.classList.remove('selected');x.removeAttribute('aria-pressed')});b.classList.add('selected');b.setAttribute('aria-pressed','true');const page=pageById(b.dataset.pageId);let index=Number(b.dataset.flowWord),text;if(b.dataset.flowHit!==undefined){const words=U.view==='photo'?F.photos.find(p=>p.pageId===page.id)?.words:page.words,w=words?.[Number(b.dataset.flowHit)];if(!w)return;index=U.view==='photo'?w.index:Number(b.dataset.flowHit);text=w.text}else text=page.words[index]?.text;localLookup(page,index,text)},{capture:true});
$('#sourceContent').addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)&&e.target.dataset.flowHit!==undefined){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}))}});
let answerKeys={};json('library/answer-keys.json').then(x=>answerKeys=x.answers).catch(()=>{});
function answerState(year,q){const key=year+'-'+q,confirmed=flowData.confirmed[key],standard=answerKeys[key];return {confirmed,standard,wrong:!!(confirmed?.answer&&standard?.verified&&confirmed.answer!==standard.answer)}}
renderQuestions=function(){baseQuestions();if(!U.question)return;const key=recordKey(),state=answerState(U.page.year,U.question),box=$('#answerEditor');const badge=make('p','grade'+(state.wrong?' wrong':''),state.confirmed?(state.standard?.verified?(state.wrong?'已确认 · 错题':'已确认 · 回答正确')+' · 标准答案 '+state.standard.answer:'已确认作答 · 暂无可靠标准答案，暂不能核验'):'待确认作答 · 不计入错题统计');box.append(badge);const actions=make('div','flow-actions');for(const [label,fn]of [['确认当前答案',()=>{const answer=U.records[key]?.answer;if(!answer){toast('请先选择你的原始答案');return}flowData.confirmed[key]={answer,confidence:1,method:'manual',confirmedAt:new Date().toISOString()};saveFlow();renderQuestions()}],['问 AI / 错因分析',()=>openChat(state.wrong?'analysis':'chat')],['标记掌握',()=>{flowData.mastered[key]=!flowData.mastered[key];saveFlow();toast(flowData.mastered[key]?'已标记掌握':'已取消掌握')}],['原文证据',()=>jumpEvidence()]]){const b=make('button','',label);b.onclick=fn;actions.append(b)}box.append(actions)};
setAnswer=function(answer){delete flowData.confirmed[recordKey()];saveFlow();baseSetAnswer(answer)};

function jumpEvidence(){
 const standard=answerKeys[recordKey()],phrase=standard?.evidence;if(!phrase){mobilePane('source');jumpSource(U.page.id);toast('尚无核验的证据片段，请对照原文和解析查找');return}
 const normalize=s=>s.toLowerCase().replace(/[^a-z0-9]/g,'');const parts=phrase.split(/\s+/).map(normalize);
 for(const p of U.pages.filter(p=>p.year===U.page.year)){const ws=p.words.map(w=>normalize(w.text));const i=ws.findIndex((w,n)=>parts.every((part,j)=>part===ws[n+j]));if(i>=0){mobilePane('source');jumpSource(p.id,i);return}}
 mobilePane('source');jumpSource(U.page.id);toast('证据文字未精确对齐，请核对所在段落');
}

function nextWrong(){const list=Object.keys(flowData.confirmed).filter(key=>{const [y,q]=key.split('-').map(Number);return answerState(y,q).wrong&&!flowData.mastered[key]}).sort();if(!list.length){toast('没有尚未掌握的已核验错题');return}const current=U.page&&U.question?recordKey():'',key=list[(list.indexOf(current)+1)%list.length],[year,q]=key.split('-').map(Number),page=U.pages.find(p=>p.year===year&&p.questions.some(x=>x.number===q));openPage(page).then(()=>{U.question=q;renderQuestions();showExplanation()})}
async function sha(text){const b=typeof text==='string'?new TextEncoder().encode(text):text;return [...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function apiConfig(){return {available:false,models:{}}}
function chatContext(){const page=currentSource(),key=page.year+'-'+U.question,state=answerState(page.year,U.question),question=activeQuestions().find(q=>q.number===U.question),bodyPage=page.page<=10&&page.page%2===0?pageById(page.year+'-'+(page.page-1)):page;const refs=(U.refs.get(page.year)||[]),ranked=ExamMatch.references(question?.text||page.text,refs,2,U.question);return {year:page.year,page:page.page,section:page.section,question:U.question,questionText:question?.text||'',passage:bodyPage?.text.slice(0,14000),selected:F.selection?.text||'',sentence:sentenceFor(page,F.selection?.index)?.english||'',answer:state.confirmed?.answer||null,standard:state.standard?.verified?state.standard:null,references:ranked.map(r=>({source:meta(page.year).sourceReference,page:r.page.page,text:r.page.text.slice(0,4000)}))}}
function drawChat(){const box=$('#chatLog');box.replaceChildren();for(const m of flowData.chats[F.chatKey]||[])box.append(make('div','chat-message '+m.role,m.text));box.scrollTop=box.scrollHeight}
async function openChat(kind='chat'){if(!U.page)return;F.chatKey=U.page.year+'-'+(U.question||'page'+U.page.page);$('#chatDrawer').hidden=false;$('#chatTitle').textContent=U.page.year+' 年 · '+(U.question?'第 '+U.question+' 题':'第 '+U.page.page+' 页');$('#chatKind').value=kind;drawChat();$('#chatContext').textContent='只发送本题原文、已确认答案和最多 2 页相关解析摘录。扫描页 OCR 不完整时会说明依据不足。';await modelLabel()}
async function modelLabel(){try{const c=await apiConfig(),deep=$('#chatDepth').value==='deep';$('#modelLabel').textContent=(c.available?'本次将调用：':'尚未配置密钥 · 计划使用：')+(deep?c.models.review:c.models[$('#chatKind').value])+(deep?' · 深度模式费用较高':' · 省额度模式')}catch(e){$('#modelLabel').textContent=e.message}}
async function sendChat(){toast('请使用当前题上下文导出入口')}
function showVocab(){dialog('真题语境复习卡',Object.values(flowData.vocabulary).length?Object.entries(flowData.vocabulary).map(([key,v])=>'<div class="vocab-card"><strong>'+esc(v.word)+' · '+esc(v.state)+'</strong><p>'+esc(v.sentence)+'</p><details><summary>显示译文</summary>'+esc(v.translation||'本句译文待生成')+'</details><button data-card="'+esc(key)+'">回到原题</button></div>').join(''):'尚未标记生词。点词后选择“模糊”或“不认识”。');document.querySelectorAll('[data-card]').forEach(b=>b.onclick=()=>{const v=flowData.vocabulary[b.dataset.card];$('#dialog').close();openPage(pageById(v.pageId)).then(()=>localLookup(pageById(v.pageId),v.index,v.word))})}
function privacy(){dialog('保存与隐私','<p>照片、导入解析和索引保存在本机 IndexedDB；答案、笔记、对话与单词状态保存在本机浏览器。不同设备不会自动同步。</p><p>点读和印刷文字 OCR 不调用 AI。仅在你点击“识别作答”或“发送 / 分析”时，才把当前题目的必要照片裁剪或文本发送到本站服务端，再发送给 OpenAI。</p><p>旧版记录保持独立，升级不删除旧数据。JSON 备份不包含照片与 PDF；请保留源文件。</p><div class="flow-actions"><button id="exportFlow">导出新版记录</button><button id="privacyPhotos">管理照片</button><button id="managePDFs">管理导入解析</button></div>');$('#exportFlow').onclick=()=>download(flowData,'英语二-瀑布版记录.json');$('#privacyPhotos').onclick=showHistory;$('#managePDFs').onclick=()=>globalThis.managePDFs?.()}
function installFlow(){const css=make('link');css.rel='stylesheet';css.href='flow.css';document.head.append(css);const bar=make('nav','quickbar');bar.id='quickbar';bar.hidden=true;bar.setAttribute('aria-label','阅读快捷栏');bar.innerHTML='<button data-mode="word">单词</button><button data-mode="sentence">句子</button><button id="currentQuestion">当前题</button><button id="askAI">问 AI</button><button id="nextWrong">下一错题</button><button id="toTop">顶部</button>';document.body.append(bar);const location=make('span');location.id='flowLocation';$('.work-controls').append(location);const switcher=make('div','mobile-source');switcher.innerHTML='<button data-mobile="source">原题 / 点读</button><button data-mobile="review">译文 / 解析</button>';$('.work-controls').append(switcher);for(const b of switcher.children)b.onclick=()=>mobilePane(b.dataset.mobile);const actions=make('div','flow-actions');actions.innerHTML='<button id="vocabCards">生词卡</button><button id="importPDF">导入解析 PDF</button><button id="privacy">保存与隐私</button><button id="scanAnswers">识别作答 / 确认</button>';$('.work-heading').after(actions);$('#currentQuestion').onclick=()=>{mobilePane('review');$('#questionBar').scrollIntoView({block:'center',behavior:'smooth'})};$('#askAI').onclick=()=>openChat();$('#nextWrong').onclick=nextWrong;$('#toTop').onclick=()=>{window.scrollTo({top:0,behavior:'smooth'});$('#sourceContent').scrollTo({top:0,behavior:'smooth'})};$('#vocabCards').onclick=showVocab;$('#privacy').onclick=privacy;$('#backHome').addEventListener('click',()=>bar.hidden=true);const drawer=make('section','chat-drawer');drawer.id='chatDrawer';drawer.hidden=true;drawer.setAttribute('aria-label','当前题 AI 对话');drawer.innerHTML='<div class="chat-head"><h2 id="chatTitle"></h2><button id="closeChat" aria-label="关闭 AI 对话">×</button></div><p class="source-tag">AI 补充分析 · 与原书解析分开展示</p><div class="chat-controls"><select id="chatDepth" aria-label="AI 调用模式"><option value="economy">省额度</option><option value="deep">深度解析（主动升级）</option></select><select id="chatKind" aria-label="AI 任务"><option value="chat">上下文问答</option><option value="analysis">错因分析</option></select></div><p id="modelLabel" class="muted"></p><details><summary>发送哪些内容</summary><p id="chatContext" class="muted"></p></details><div class="chat-shorts"></div><div id="chatLog" class="chat-log" role="log" aria-live="polite"></div><div class="chat-compose"><textarea id="chatInput" maxlength="6000" placeholder="结合当前题提问…" aria-label="问题"></textarea><div class="flow-actions"><button id="chatSend" class="primary">发送 / 分析</button><button id="chatStop">停止</button><button id="chatRetry">重试</button><button id="chatClear">清空本题对话</button></div></div>';document.body.append(drawer);$('#closeChat').onclick=()=>drawer.hidden=true;$('#chatDepth').onchange=modelLabel;$('#chatKind').onchange=modelLabel;$('#chatSend').onclick=()=>sendChat();$('#chatRetry').onclick=()=>sendChat(true);$('#chatStop').onclick=()=>F.controller?.abort();$('#chatClear').onclick=()=>{if(F.controller){toast('请先停止生成');return}flowData.chats[F.chatKey]=[];saveFlow();drawChat()};for(const q of ['为什么不能选我这个答案','定位原文依据','分析长难句','解释同义替换','给我一道相似判断题']){const b=make('button','',q);b.onclick=()=>$('#chatInput').value=q;$('.chat-shorts').append(b)}document.addEventListener('keydown',e=>{if(e.key==='Escape')drawer.hidden=true});$('#pageSelect').onchange=e=>{const p=pageById(e.target.value);updateLocation(p,true);jumpSource(p.id);showExplanation()};window.addEventListener('offline',()=>toast('已离线：已缓存的点读与资料仍可阅读'));if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});}
installFlow();
